const input = $json || {};
const clean = (value) => value === undefined || value === null ? '' : String(value).trim();
const toDeterministicUuid = (value) => {
  const raw = clean(value);
  if (/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(raw)) return raw.toLowerCase();
  const source = raw || 'handoff-channel';
  const hash = (seed) => { let h = seed >>> 0; for (let i = 0; i < source.length; i += 1) { h ^= source.charCodeAt(i); h = Math.imul(h, 16777619); } return (h >>> 0).toString(16).padStart(8, '0'); };
  let hex = [0x811c9dc5, 0x9e3779b9, 0x85ebca6b, 0xc2b2ae35].map(hash).join('');
  hex = `${hex.slice(0, 12)}5${hex.slice(13, 16)}a${hex.slice(17)}`;
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20, 32)}`;
};
const rawChannelId = clean(input.channel_id);
const normalizedChannelId = rawChannelId || null;
return { json: {
  clinic_id: clean(input.clinic_id),
  conversation_id: clean(input.conversation_id),
  patient_id: clean(input.patient_id),
  channel_type: clean(input.channel_type).toLowerCase(),
  channel_id: rawChannelId || null,
  handoff_reason: clean(input.handoff_reason),
  reason_code: clean(input.reason_code).toUpperCase(),
  reason_note: clean(input.reason_note) || null,
  correlation_id: clean(input.correlation_id),
  source_message_id: clean(input.source_message_id) || null,
  priority: clean(input.priority || 'NORMAL').toUpperCase(),
  context_snapshot: input.context_snapshot && typeof input.context_snapshot === 'object' && !Array.isArray(input.context_snapshot) ? input.context_snapshot : {},
  metadata: { ...(input.metadata && typeof input.metadata === 'object' && !Array.isArray(input.metadata) ? input.metadata : {}), raw_channel_id: rawChannelId || null, normalized_channel_id: normalizedChannelId }
} };

const raw = $json || {};
let result = raw.result ?? raw;
if (typeof result === 'string') {
  try { result = JSON.parse(result); } catch (error) { result = { success: false, code: 'DATABASE_ERROR', handoff: null }; }
}
return { json: {
  success: result.success === true,
  code: result.code || (result.success === true ? 'HANDOFF_CREATED' : 'INTERNAL_ERROR'),
  handoff: result.handoff || null,
  conversation_id: result.conversation_id || $('Normalize Handoff Input').item.json.conversation_id || null,
  correlation_id: result.correlation_id || $('Normalize Handoff Input').item.json.correlation_id || null,
  created: result.created === true,
  audit_status: result.audit_status || null,
  audit_error: result.audit_error || null
} };
